#include <list>
#include <algorithm>
#include <iostream>

struct Data { int id; int value; };

int main() {
    std::list<Data> l = {{1, 10}, {2, 5}, {3, 10}, {4, 15}};

    // Sort by value, demonstrating stability (id 1 and 3 are equal)
    l.sort([](const Data& a, const Data& b) {
        return a.value < b.value;
    });

    // Output order: (2, 5), (1, 10), (3, 10), (4, 15)
    // Order of (1, 10) and (3, 10) is preserved relative to insertion.
}
